CREATE OR REPLACE FUNCTION public.spend_role() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN public.is_erp_admin(auth.uid()) THEN 'finance' WHEN EXISTS(SELECT 1 FROM public.user_app_access WHERE user_id=auth.uid() AND app_key='spend') THEN CASE WHEN EXISTS(SELECT 1 FROM public.user_app_access WHERE user_id=auth.uid() AND app_key='cash_flow') THEN 'finance' ELSE 'holder' END END $$;
REVOKE ALL ON FUNCTION public.spend_role() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.spend_role() TO authenticated;
CREATE TABLE public.spend_cards(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_key uuid NOT NULL DEFAULT gen_random_uuid(), company_name text NOT NULL, name text NOT NULL, bank text NOT NULL, last_four text NOT NULL CHECK(last_four ~ '^[0-9]{4}$'), holder_id uuid NOT NULL REFERENCES public.profiles(id), due_day integer NOT NULL DEFAULT 10 CHECK(due_day BETWEEN 1 AND 31), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.spend_cards TO authenticated; GRANT ALL ON public.spend_cards TO service_role; ALTER TABLE public.spend_cards ENABLE ROW LEVEL SECURITY;
CREATE POLICY spend_cards_read ON public.spend_cards FOR SELECT TO authenticated USING(public.spend_role()='finance' OR (public.spend_role()='holder' AND holder_id=auth.uid()));
CREATE OR REPLACE FUNCTION public.spend_card_access(_card uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.spend_role() IS NOT NULL AND EXISTS(SELECT 1 FROM public.spend_cards WHERE id=_card AND (public.spend_role()='finance' OR holder_id=auth.uid())) $$;
REVOKE ALL ON FUNCTION public.spend_card_access(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.spend_card_access(uuid) TO authenticated;
CREATE TABLE public.spend_receipts(id uuid PRIMARY KEY, card_id uuid NOT NULL REFERENCES public.spend_cards(id), holder_id uuid NOT NULL REFERENCES public.profiles(id), date date NOT NULL, merchant text NOT NULL, amount numeric(14,2) NOT NULL CHECK(amount>0), category text NOT NULL, observation text NOT NULL DEFAULT '', project_id uuid REFERENCES public.projects(id), file_path text NOT NULL UNIQUE, clear_photo boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','matched','approved','adjustment')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.spend_receipts TO authenticated; GRANT ALL ON public.spend_receipts TO service_role; ALTER TABLE public.spend_receipts ENABLE ROW LEVEL SECURITY;
CREATE POLICY spend_receipts_read ON public.spend_receipts FOR SELECT TO authenticated USING(public.spend_card_access(card_id));
CREATE TABLE public.spend_statements(id uuid PRIMARY KEY, card_id uuid NOT NULL REFERENCES public.spend_cards(id), period date NOT NULL, due_date date NOT NULL, file_path text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(card_id,period));
GRANT SELECT ON public.spend_statements TO authenticated; GRANT ALL ON public.spend_statements TO service_role; ALTER TABLE public.spend_statements ENABLE ROW LEVEL SECURITY;
CREATE POLICY spend_statements_read ON public.spend_statements FOR SELECT TO authenticated USING(public.spend_card_access(card_id));
CREATE TABLE public.spend_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), statement_id uuid NOT NULL REFERENCES public.spend_statements(id), ordinal integer NOT NULL, date date NOT NULL, merchant text NOT NULL, amount numeric(14,2) NOT NULL, installment text, last_four text, receipt_id uuid UNIQUE REFERENCES public.spend_receipts(id), category text, account_id uuid REFERENCES public.cash_flow_accounts(id), cost_center_id uuid REFERENCES public.cost_centers(id), project_id uuid REFERENCES public.projects(id), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','matched','approved','adjustment')), payable_id uuid UNIQUE REFERENCES public.cash_flow_payables(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(statement_id,ordinal));
GRANT SELECT ON public.spend_lines TO authenticated; GRANT ALL ON public.spend_lines TO service_role; ALTER TABLE public.spend_lines ENABLE ROW LEVEL SECURITY;
CREATE POLICY spend_lines_read ON public.spend_lines FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.spend_statements s WHERE s.id=statement_id AND public.spend_card_access(s.card_id)));
CREATE TABLE public.spend_notices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), card_id uuid NOT NULL REFERENCES public.spend_cards(id), line_id uuid REFERENCES public.spend_lines(id), message text NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.spend_notices TO authenticated; GRANT ALL ON public.spend_notices TO service_role; ALTER TABLE public.spend_notices ENABLE ROW LEVEL SECURITY;
CREATE POLICY spend_notices_read ON public.spend_notices FOR SELECT TO authenticated USING(public.spend_card_access(card_id));
CREATE TABLE public.spend_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), card_id uuid NOT NULL REFERENCES public.spend_cards(id), actor_id uuid NOT NULL, action text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.spend_logs TO authenticated; GRANT ALL ON public.spend_logs TO service_role; ALTER TABLE public.spend_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY spend_logs_read ON public.spend_logs FOR SELECT TO authenticated USING(public.spend_card_access(card_id));
ALTER TABLE public.cash_flow_payables ADD COLUMN spend_line_id uuid UNIQUE REFERENCES public.spend_lines(id);
CREATE OR REPLACE FUNCTION public.spend_storage_access(_name text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN EXISTS(SELECT 1 FROM public.spend_cards c WHERE c.company_key::text=split_part(_name,'/',1) AND c.id::text=split_part(_name,'/',3) AND split_part(_name,'/',2) ~ '^[0-9]{4}-[0-9]{2}$' AND public.spend_card_access(c.id)); END $$;
REVOKE ALL ON FUNCTION public.spend_storage_access(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.spend_storage_access(text) TO authenticated;
CREATE POLICY spend_files_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='spend-files' AND public.spend_storage_access(name));
CREATE POLICY spend_files_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='spend-files' AND owner_id=auth.uid()::text AND public.spend_storage_access(name));
CREATE POLICY spend_files_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='spend-files' AND owner_id=auth.uid()::text AND public.spend_storage_access(name) AND NOT EXISTS(SELECT 1 FROM public.spend_receipts WHERE file_path=name) AND NOT EXISTS(SELECT 1 FROM public.spend_statements WHERE file_path=name));
CREATE OR REPLACE FUNCTION public.spend_workspace() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE r text:=public.spend_role(); BEGIN IF r IS NULL THEN RAISE EXCEPTION 'Acesso ao Spend não autorizado'; END IF; RETURN jsonb_build_object('role',r,'user_id',auth.uid(),'cards',coalesce((SELECT jsonb_agg(to_jsonb(c)) FROM public.spend_cards c WHERE public.spend_card_access(c.id)),'[]'),'receipts',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.date DESC) FROM public.spend_receipts x WHERE public.spend_card_access(x.card_id)),'[]'),'statements',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.spend_statements x WHERE public.spend_card_access(x.card_id)),'[]'),'lines',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.ordinal) FROM public.spend_lines x JOIN public.spend_statements s ON s.id=x.statement_id WHERE public.spend_card_access(s.card_id)),'[]'),'notices',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM public.spend_notices x WHERE public.spend_card_access(x.card_id)),'[]'),'logs',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM public.spend_logs x WHERE public.spend_card_access(x.card_id)),'[]'),'users',coalesce((SELECT jsonb_agg(jsonb_build_object('id',p.id,'name',p.full_name)) FROM public.profiles p WHERE p.is_active AND p.deleted_at IS NULL AND (r='finance' OR p.id=auth.uid())),'[]'),'projects',coalesce((SELECT jsonb_agg(jsonb_build_object('id',p.id,'name',p.name)) FROM public.projects p WHERE p.status='active' AND (r='finance' OR p.created_by=auth.uid())),'[]'),'accounts',CASE WHEN r='finance' THEN coalesce((SELECT jsonb_agg(jsonb_build_object('id',a.id,'name',a.code || ' · ' || a.name)) FROM public.cash_flow_accounts a WHERE a.active AND a.accepts_entries AND NOT EXISTS(SELECT 1 FROM public.cash_flow_accounts b WHERE b.active AND b.parent_id=a.id)),'[]'::jsonb) ELSE '[]'::jsonb END,'centers',CASE WHEN r='finance' THEN coalesce((SELECT jsonb_agg(jsonb_build_object('id',c.id,'name',c.name)) FROM public.cost_centers c WHERE c.active),'[]'::jsonb) ELSE '[]'::jsonb END,'settings',coalesce((SELECT variant_key::jsonb FROM public.cde_selected WHERE group_key='spend_categories' AND is_primary),'{}'::jsonb)); END $$;
REVOKE ALL ON FUNCTION public.spend_workspace() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.spend_workspace() TO authenticated;
CREATE OR REPLACE FUNCTION public.spend_action(_action text,_data jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE r text:=public.spend_role(); c public.spend_cards; s public.spend_statements; l public.spend_lines; receipt public.spend_receipts; v jsonb; rid uuid; pid uuid; cat text; cfg jsonb; cnt integer; path text; BEGIN
IF r IS NULL THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF;
IF _action='card' THEN
 IF r<>'finance' THEN RAISE EXCEPTION 'Somente Financeiro'; END IF;
 IF trim(coalesce(_data->>'name',''))='' OR trim(coalesce(_data->>'company_name',''))='' OR trim(coalesce(_data->>'bank',''))='' THEN RAISE EXCEPTION 'Informe nome, empresa e banco'; END IF;
 INSERT INTO public.spend_cards(id,name,company_name,bank,last_four,holder_id,due_day) VALUES((_data->>'id')::uuid,_data->>'name',_data->>'company_name',_data->>'bank',_data->>'last_four',(_data->>'holder_id')::uuid,(_data->>'due_day')::int) ON CONFLICT(id) DO UPDATE SET name=excluded.name,company_name=excluded.company_name,bank=excluded.bank,last_four=excluded.last_four,due_day=excluded.due_day WHERE spend_cards.holder_id=excluded.holder_id RETURNING * INTO c;
 IF c.id IS NULL THEN RAISE EXCEPTION 'O portador original deve ser preservado; cadastre outro cartão'; END IF;
 INSERT INTO public.spend_logs(card_id,actor_id,action,details) VALUES(c.id,auth.uid(),'card',_data); RETURN to_jsonb(c);
END IF;
IF _action='receipt' THEN
 SELECT * INTO c FROM public.spend_cards WHERE id=(_data->>'card_id')::uuid AND active; IF c.id IS NULL OR NOT public.spend_card_access(c.id) THEN RAISE EXCEPTION 'Cartão não autorizado'; END IF;
 cat:=_data->>'category'; path:=_data->>'file_path';
 IF cat NOT IN ('alimentacao','transporte','estacionamento','pedagio','ferramentas','insumos','servicos','ia','software','outros') THEN RAISE EXCEPTION 'Categoria inválida'; END IF;
 IF cat='insumos' AND nullif(_data->>'project_id','') IS NULL THEN RAISE EXCEPTION 'Insumos exige Projeto'; END IF;
 IF cat IN ('servicos','outros') AND trim(coalesce(_data->>'observation',''))='' THEN RAISE EXCEPTION 'Informe a observação/especificação'; END IF;
 IF cat='ferramentas' AND NOT coalesce((_data->>'clear_photo')::boolean,false) THEN RAISE EXCEPTION 'Confirme foto nítida da NF/cupom'; END IF;
 IF (_data->>'amount')::numeric<=0 OR trim(coalesce(_data->>'merchant',''))='' THEN RAISE EXCEPTION 'Informe valor e estabelecimento'; END IF;
 IF nullif(_data->>'project_id','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.projects p WHERE p.id=(_data->>'project_id')::uuid AND p.status='active' AND (r='finance' OR p.created_by=auth.uid())) THEN RAISE EXCEPTION 'Projeto não autorizado'; END IF;
 IF NOT public.spend_storage_access(path) OR split_part(path,'/',3)<>c.id::text OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='spend-files' AND name=path AND (r='finance' OR owner_id=auth.uid()::text)) THEN RAISE EXCEPTION 'Comprovante não autorizado'; END IF;
 INSERT INTO public.spend_receipts(id,card_id,holder_id,date,merchant,amount,category,observation,project_id,file_path,clear_photo) VALUES((_data->>'id')::uuid,c.id,c.holder_id,(_data->>'date')::date,_data->>'merchant',(_data->>'amount')::numeric,cat,coalesce(_data->>'observation',''),nullif(_data->>'project_id','')::uuid,path,coalesce((_data->>'clear_photo')::boolean,false)) ON CONFLICT(id) DO NOTHING RETURNING id INTO rid;
 IF rid IS NOT NULL THEN INSERT INTO public.spend_logs(card_id,actor_id,action,details) VALUES(c.id,auth.uid(),'receipt',jsonb_build_object('receipt_id',rid)); END IF;
 RETURN jsonb_build_object('ok',true);
END IF;
IF r<>'finance' THEN RAISE EXCEPTION 'Somente Financeiro'; END IF;
IF _action='statement' THEN
 SELECT * INTO c FROM public.spend_cards WHERE id=(_data->>'card_id')::uuid AND active; path:=_data->>'file_path';
 IF c.id IS NULL OR NOT public.spend_storage_access(path) OR split_part(path,'/',3)<>c.id::text OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='spend-files' AND name=path) THEN RAISE EXCEPTION 'Fatura não autorizada'; END IF;
 IF jsonb_array_length(_data->'lancamentos')=0 THEN RAISE EXCEPTION 'Fatura sem lançamentos'; END IF;
 INSERT INTO public.spend_statements(id,card_id,period,due_date,file_path) VALUES((_data->>'id')::uuid,c.id,date_trunc('month',(_data->>'period')::date)::date,(_data->>'due_date')::date,path) ON CONFLICT(id) DO NOTHING RETURNING * INTO s;
 IF s.id IS NULL THEN RETURN jsonb_build_object('ok',true); END IF;
 cnt:=0; FOR v IN SELECT * FROM jsonb_array_elements(_data->'lancamentos') LOOP cnt:=cnt+1;
 INSERT INTO public.spend_lines(statement_id,ordinal,date,merchant,amount,installment,last_four) VALUES(s.id,cnt,(v->>'data')::date,v->>'estabelecimento',(v->>'valor')::numeric,v->>'parcela',v->>'final_cartao'); END LOOP;
 INSERT INTO public.spend_logs(card_id,actor_id,action,details) VALUES(c.id,auth.uid(),'statement',jsonb_build_object('statement_id',s.id,'count',cnt)); RETURN jsonb_build_object('ok',true);
END IF;
IF _action='automatch' THEN
 SELECT * INTO s FROM public.spend_statements WHERE id=(_data->>'statement_id')::uuid FOR UPDATE; IF s.id IS NULL THEN RAISE EXCEPTION 'Fatura não encontrada'; END IF; SELECT * INTO c FROM public.spend_cards WHERE id=s.card_id;
 FOR l IN SELECT * FROM public.spend_lines WHERE statement_id=s.id AND receipt_id IS NULL AND status='pending' ORDER BY ordinal FOR UPDATE LOOP
 SELECT count(*),min(x.id::text)::uuid INTO cnt,rid FROM public.spend_receipts x WHERE x.card_id=c.id AND x.holder_id=c.holder_id AND x.amount=l.amount AND abs(x.date-l.date)<=2 AND l.last_four=c.last_four AND x.status='pending' AND NOT EXISTS(SELECT 1 FROM public.spend_lines y WHERE y.receipt_id=x.id);
 IF cnt=1 AND (SELECT count(*) FROM public.spend_lines y WHERE y.statement_id=s.id AND y.receipt_id IS NULL AND y.amount=l.amount AND abs(y.date-(SELECT date FROM public.spend_receipts WHERE id=rid))<=2 AND y.last_four=c.last_four)=1 THEN
 SELECT * INTO receipt FROM public.spend_receipts WHERE id=rid FOR UPDATE; IF receipt.status<>'pending' OR EXISTS(SELECT 1 FROM public.spend_lines WHERE receipt_id=rid) THEN CONTINUE; END IF;
 SELECT variant_key::jsonb->receipt.category INTO cfg FROM public.cde_selected WHERE group_key='spend_categories' AND is_primary;
 UPDATE public.spend_lines SET receipt_id=rid,status='matched',category=receipt.category,project_id=receipt.project_id,account_id=nullif(cfg->>'account_id','')::uuid,cost_center_id=nullif(cfg->>'cost_center_id','')::uuid WHERE id=l.id; UPDATE public.spend_receipts SET status='matched' WHERE id=rid;
 INSERT INTO public.spend_logs(card_id,actor_id,action,details) VALUES(c.id,auth.uid(),'matched',jsonb_build_object('line_id',l.id,'receipt_id',rid)); END IF; END LOOP; RETURN jsonb_build_object('ok',true);
END IF;
SELECT * INTO l FROM public.spend_lines WHERE id=(_data->>'line_id')::uuid FOR UPDATE; IF l.id IS NULL THEN RAISE EXCEPTION 'Lançamento não encontrado'; END IF; SELECT * INTO s FROM public.spend_statements WHERE id=l.statement_id; SELECT * INTO c FROM public.spend_cards WHERE id=s.card_id;
IF l.status='approved' THEN IF _action='approve' THEN RETURN jsonb_build_object('ok',true,'payable_id',l.payable_id); END IF; RAISE EXCEPTION 'Lançamento aprovado não pode ser alterado'; END IF;
IF _action='notify' OR _action='adjustment' THEN IF trim(coalesce(_data->>'message',''))='' THEN RAISE EXCEPTION 'Informe a mensagem'; END IF; INSERT INTO public.spend_notices(card_id,line_id,message,created_by) VALUES(c.id,l.id,_data->>'message',auth.uid()); IF _action='adjustment' THEN UPDATE public.spend_lines SET status='adjustment' WHERE id=l.id; IF l.receipt_id IS NOT NULL THEN UPDATE public.spend_receipts SET status='adjustment' WHERE id=l.receipt_id; END IF; END IF;
ELSIF _action='link' THEN
 SELECT * INTO receipt FROM public.spend_receipts WHERE id=(_data->>'receipt_id')::uuid FOR UPDATE; IF receipt.card_id<>c.id OR receipt.id IS NULL OR receipt.amount<>l.amount OR abs(receipt.date-l.date)>2 OR l.last_four IS DISTINCT FROM c.last_four THEN RAISE EXCEPTION 'Data, valor ou cartão não correspondem'; END IF;
 IF EXISTS(SELECT 1 FROM public.spend_lines WHERE receipt_id=receipt.id AND id<>l.id) THEN RAISE EXCEPTION 'Comprovante já vinculado'; END IF;
 UPDATE public.spend_lines SET receipt_id=receipt.id,category=receipt.category,project_id=receipt.project_id,status='matched' WHERE id=l.id; UPDATE public.spend_receipts SET status='matched' WHERE id=receipt.id;
ELSIF _action='approve' THEN
 IF l.receipt_id IS NULL THEN RAISE EXCEPTION 'Anexe o comprovante ou Invoice antes de aprovar'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.cash_flow_accounts a WHERE a.id=(_data->>'account_id')::uuid AND a.active AND a.accepts_entries AND NOT EXISTS(SELECT 1 FROM public.cash_flow_accounts b WHERE b.parent_id=a.id AND b.active)) THEN RAISE EXCEPTION 'Selecione conta contábil válida'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.cost_centers WHERE id=(_data->>'cost_center_id')::uuid AND active) THEN RAISE EXCEPTION 'Selecione Centro de Custo'; END IF;
 pid:=nullif(_data->>'project_id','')::uuid; SELECT * INTO receipt FROM public.spend_receipts WHERE id=l.receipt_id;
 IF receipt.category='insumos' AND pid IS NULL THEN RAISE EXCEPTION 'Insumos exige Projeto'; END IF;
 IF pid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.projects WHERE id=pid AND status='active') THEN RAISE EXCEPTION 'Projeto inativo'; END IF;
 IF l.amount<=0 THEN RAISE EXCEPTION 'Créditos e estornos exigem tratamento específico no Finance'; END IF;
 INSERT INTO public.cash_flow_payables(spend_line_id,request_type,item_name,requester_id,project_id,client_id,client_unit_id,cost_center_id,account_id,amount,due_date,status,classified_by,classified_at,fiscal_period,competence_period,cash_period) VALUES(l.id,'Cartão',c.name || ' · ' || l.merchant,c.holder_id,pid,(SELECT client_id FROM public.projects WHERE id=pid),(SELECT client_unit_id FROM public.projects WHERE id=pid),(_data->>'cost_center_id')::uuid,(_data->>'account_id')::uuid,l.amount,s.due_date,'a_pagar',auth.uid(),now(),s.period,date_trunc('month',l.date)::date,date_trunc('month',s.due_date)::date) RETURNING id INTO rid;
 UPDATE public.spend_lines SET status='approved',payable_id=rid,account_id=(_data->>'account_id')::uuid,cost_center_id=(_data->>'cost_center_id')::uuid,project_id=pid WHERE id=l.id; UPDATE public.spend_receipts SET status='approved' WHERE id=l.receipt_id;
ELSE RAISE EXCEPTION 'Ação inválida'; END IF;
INSERT INTO public.spend_logs(card_id,actor_id,action,details) VALUES(c.id,auth.uid(),_action,_data); RETURN jsonb_build_object('ok',true); END $$;
REVOKE ALL ON FUNCTION public.spend_action(text,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.spend_action(text,jsonb) TO authenticated;